NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Petrus, ein Apostel von Jesus Christus. /An die erwählten Fremden der Zerstreuung, in Pontus, Galatia, Kappadokia, Asia und Bithynia, /',
        2: '[erwählt] gemäß der Vorkenntnis Gottes des Vaters, durch die Heiligung des Geistes, zum Gehorsam und zur Besprengung mit dem Blut von Jesus Christus: /Gnade und Friede möge euch vermehrt werden!',
        3: 'Gelobt [sei] der Gott und Vater unseres Herrn Jesus Christus, der uns entsprechend seiner großen Barmherzigkeit wiedergeboren hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten,',
        4: 'zu einem unvergänglichen und unbefleckten und unverwüstlichen Erbe, das in den Himmeln aufbewahrt wird für euch,',
        5: 'die ihr mit der Kraft Gottes durch Glauben bewahrt werdet zu einem Heil, das bereit [ist], offenbart zu werden in der letzten Zeit;',
        6: 'darüber werdet ihr euch freuen, obwohl ihr jetzt für kurze [Zeit] – wenn es notwendig ist – in verschiedenen Anfechtungen betrübt worden seid,',
        7: 'damit die Echtheit eures Glaubens ([die ist] viel kostbarer als Gold, das vergeht, aber das durch Feuer [auf Echtheit] geprüft wird) Anlass gibt zu Lob und Herrlichkeit und Ehre bei der Offenbarung von Jesus Christus;',
        8: 'den liebt ihr, obwohl ihr ihn nicht gesehen habt, und an den glaubt ihr, obwohl ihr ihn jetzt nicht seht, und jubelt mit unaussprechlicher und herrlicher Freude,',
        9: 'wenn ihr das Ziel eures Glaubens erlangt: Seelenheil.',
        10: 'Über dieses Heil haben die Propheten, die hinsichtlich der euch [geltenden] Gnade geweissagt haben, nachgesucht und nachgeforscht,',
        11: 'um herauszufinden, auf wen oder welche Zeit der Geist des Christus in ihnen hindeutete, als er die Leiden für Christus und die Herrlichkeiten danach vorab bezeugte.',
        12: 'Ihnen wurde offenbart, dass sie nicht sich selbst, sondern euch hinsichtlich der [Dinge] dienten, die euch jetzt verkündet wurden durch diejenigen, die euch die gute Nachricht verkündet haben durch den heiligen Geist, der vom Himmel gesandt wurde – [Dinge], auf die [sogar] Engel zu sehen wünschen.',
        13: 'Darum umgürtet die Lenden eures Verstandes und seid nüchtern! Hofft ausschließlich auf die Gnade, die euch gebracht wird durch die Offenbarung von Jesus Christus!',
        14: 'Als gehorsame Kinder passt euch nicht den Begierden an, denen [ihr euch] früher in eurer Unwissenheit [hingegeben habt],',
        15: 'sondern entsprechend dem Heiligen, der euch berufen hat, sollt auch ihr selbst in [eurem] ganzen Lebenswandel heilig sein.',
        16: 'Denn es steht geschrieben: „Seid heilig, weil ich heilig [bin].“',
        17: 'Und wenn ihr den als Vater anruft, der unvoreingenommen nach dem Lebenswerk eines jeden urteilt, dann verhaltet euch mit Respekt, ‹solange ihr zu Gast seid›,',
        18: 'da ihr wisst, dass ihr nicht mit vergänglichen [Dingen wie] Silber oder Gold erlöst worden seid von eurem nutzlosen Lebenswandel, den ihr von euren Vorfahren übernommen habt,',
        19: 'sondern mit dem kostbaren Blut des Christus, wie von einem makellosen und unbefleckten Lamm;',
        20: 'er war zwar vor Grundlegung der Welt auserkoren, /aber [erst] am Ende der Zeiten wurde er offenbar /um euretwillen, /',
        21: 'die ihr durch ihn an den Gott gläubig [seid], /der ihn von den Toten auferweckt und ihm Ehre gegeben hat, /damit euer Glaube und eure Hoffnung auf Gott [gerichtet] ist.',
        22: 'Nachdem ihr eure Seelen im Gehorsam gegenüber der Wahrheit zu ungeheuchelter Geschwisterliebe gereinigt habt, liebt einander inständig [und] aus reinem Herzen,',
        23: 'da ihr wiedergeboren seid, nicht aus vergänglichem, sondern aus unvergänglichem Samen, durch das lebendige und beständige Wort Gottes.',
        24: 'Denn „alles Fleisch [ist] wie Gras / und alle seine Herrlichkeit wie die Blume des Grases. / Das Gras ist verdorrt und die Blume abgefallen; /',
        25: 'aber das Wort des Herrn bleibt in Ewigkeit.“Dies wiederum ist das Wort, das euch verkündet wurde.',
    },
    2: {
        1: 'Legt also alle Bosheit und allen Betrug und Heucheleien und Neidereien und alle Verleumdungen ab.',
        2: 'Seid wie neugeborene Säuglinge begierig nach der vernünftigen, unverfälschten Milch, damit ihr durch sie zur Rettung heranwachst,',
        3: 'wenn ihr [tatsächlich] geschmeckt habt, dass der Herr gütig [ist].',
        4: 'Wenn ihr zu ihm kommt – dem lebendigen Stein, der zwar von Menschen verworfen wurde, aber bei Gott auserwählt [und] kostbar [ist] –,',
        5: 'dann werdet auch ihr selbst wie lebendige Steine als ein geistliches Haus gebaut, zu einer heiligen Priesterschaft, um geistliche Opfer darzubringen, die Gott durch Jesus Christus willkommen [sind].',
        6: 'Denn es steht in der Schrift: „Siehe, ich lege in Zion einen Stein, einen auserwählten, kostbaren Eckstein; / und wer an ihn glaubt, soll gewiss nicht enttäuscht werden.“',
        7: 'Die Kostbarkeit [gehört] also euch, die ihr glaubt; aber denen, die nicht glauben, [gilt]: „Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden“,',
        8: 'und ein „Stein zum Stoßen“und ein „Fels zum Fallen“. Sie nehmen Anstoß, da sie dem Wort ungehorsam sind, wozu sie auch bestimmt wurden.',
        9: 'Ihr hingegen [seid] ein auserwähltes Geschlecht, eine königliche Priesterschaft, eine heilige Nation, ein Volk in [Gottes] Besitz, damit ihr die Wesenszüge dessen verkündet, der euch aus der Finsternis in sein wunderbares Licht gerufen hat –',
        10: '[euch], die [ihr] früher kein Volk [wart], aber jetzt das Volk Gottes [seid]; die ihr nicht begnadigt wart, aber jetzt begnadigt worden seid.',
        11: 'Ihr Geliebten, ich ermahne euch als Gäste und Fremde [in dieser Welt], euch von fleischlichen Begierden fernzuhalten, die gegen die Seele streiten!',
        12: 'Haltet euren Lebenswandel unter den Nationen einwandfrei, damit diejenigen, die euch unterdessen als Übeltäter verleumden, [eure] guten Werke beobachten und Gott verherrlichen am Tag der Heimsuchung.',
        13: 'Ordnet euch jeder menschlichen Institution um des Herrn willen unter, ob dem König als Staatsoberhaupt',
        14: 'oder den Statthaltern als denen, die von ihm geschickt werden zur Bestrafung der Übeltäter und Belobigung der Wohltäter,',
        15: 'denn der Wille Gottes lautet folgendermaßen: durch Gutes Tun die Ignoranz der unverständigen Menschen zum Schweigen zu bringen.',
        16: '[Lebt] als freie [Menschen], aber nicht, indem ihr die Freiheit als Deckmantel der Bosheit gebraucht, sondern als Diener Gottes.',
        17: 'Respektiert alle [Menschen], liebt die Glaubensgeschwister, fürchtet Gott, ehrt den König!',
        18: 'Ihr Hausdiener sollt euch mit aller Ehrfurcht den Hausherren unterordnen, nicht nur den guten und freundlichen, sondern auch den gemeinen.',
        19: 'Denn das [ist] Gnade, wenn jemand um des vor Gott [reinen] Gewissens willen Kummer erträgt und zu Unrecht leidet.',
        20: 'Denn was [ist das] für ein Ruhm, wenn ihr es ertragt, zu sündigen und [dafür] bestraft zu werden? Doch wenn ihr es ertragt, Gutes zu tun und [dafür] zu leiden, das [ist] Gnade bei Gott.',
        21: 'Denn dazu seid ihr berufen, weil auch Christus für euch gelitten /und euch ein Vorbild hinterlassen hat, /damit ihr seinen Fußstapfen folgt; /',
        22: 'welcher keine Sünde beging, /noch Betrug in seinem Mund gefunden wurde; /',
        23: 'welcher, als er beschimpft wurde, sich nicht rächte; /als er litt, drohte er nicht, /sondern übergab [seine Sache] an den, der gerecht richtet; /',
        24: 'welcher unsere Sünden selbst hinaufgetragen hat, /mit seinem Leib an das Holz, /damit wir für die Sünden gestorben sind /und für die Gerechtigkeit leben; /durch dessen Wunden ihr geheilt geworden seid. /',
        25: 'Denn ihr wart wie Schafe umhergeirrt; /doch jetzt seid ihr zurückgekehrt zu dem Hirten und Aufseher eurer Seelen.',
    },
    3: {
        1: 'Genauso sollt ihr Frauen euch euren Ehemännern unterordnen, damit sie – auch wenn einige dem Wort misstrauen – durch den Lebenswandel [ihrer] Ehefrauen ohne ein Wort gewonnen werden,',
        2: 'wenn sie euren respektvollen, reinen Lebenswandel beobachten.',
        3: 'Euer Schmuck soll nicht die äußerliche [Art] geflochtener Haare und goldener Anhänger oder besonderer Gewänder sein,',
        4: 'sondern der verborgene Mensch des Herzens, mit der unvergänglichen [Schönheit] eines sanftmütigen und stillen Gemüts, das vor Gott viel wert ist.',
        5: 'Denn so haben sich auch die heiligen Frauen, die auf Gott hofften, früher geschmückt und sich ihren Ehemännern untergeordnet,',
        6: 'wie Sara, [die] dem Abraham gehorchte und ihn „Herr“nannte; ihre Kinder seid ihr geworden, weil ihr Gutes tut und keinerlei Einschüchterung fürchtet.',
        7: 'Genauso sollt ihr Männer einsichtig [mit ihnen] zusammenleben und dem weiblichen Geschlecht als dem schwächeren Ehre erweisen – auch als Miterben der Gnade des Lebens –, damit eure Gebete nicht behindert werden.',
        8: 'Und insbesondere [seid] alle gleichgesinnnt, verständnisvoll, umgänglich, barmherzig, demütig.',
        9: 'Zahlt nicht Schlechtes mit Schlechtem oder Beleidigung mit Beleidigung heim, sondern segnet stattdessen, weil ihr dazu berufen worden seid, Segen zu erben.',
        10: 'Denn „wer das Leben genießen und gute Tage sehen will, / soll [seine] Zunge von Schlechtem abhalten / und [seine] Lippen, um nicht hinterhältig zu reden. /',
        11: 'Er soll sich aber von Schlechtem abwenden und Gutes tun; / er soll Frieden suchen und ihm nachjagen. /',
        12: 'Denn die Augen des Herrn [achten] auf die Gerechten / und seine Ohren auf ihr Flehen; / aber das Angesicht des Herrn [ist gerichtet] gegen diejenigen, die Schlechtes tun.“',
        13: 'Und wer [ist es], der euch schaden sollte, wenn ihr Verfechter des Guten seid?',
        14: 'Doch selbst wenn ihr um der Gerechtigkeit willen leidet, [seid ihr] beglückwünschenswert. Ihre Einschüchterung aber fürchtet nicht, und erschreckt nicht,',
        15: 'sondern heiligt Christus als Herrn in euren Herzen, immer bereit zur Verteidigung gegenüber jedem, der euch nach dem Grund für die Hoffnung in euch fragt,',
        16: 'doch [tut es] mit Sanftmut und Respekt; und habt ein gutes Gewissen, sodass durch das, womit ihr verleumdet werdet, die beschämt werden, die euren guten Lebenswandel in Christus schlechtmachen.',
        17: 'Denn [es ist] besser, für Gutes Tun zu leiden (wenn es der Wille Gottes wäre) als für Böses Tun.',
        18: 'Denn auch Christus hat ein Mal für Sünden gelitten, /der Gerechte für die Ungerechten, /um euch zu Gott zu führen. /Er wurde zwar als Mensch getötet, /aber durch den Geist lebendig gemacht.',
        19: 'In diesem [Geist] ging er auch zu den Geistern im Gefängnis und predigte denen,',
        20: 'die einst ungehorsam waren, als die Geduld Gottes in den Tagen Noahs abwartete, während eine Arche konstruiert wurde, in der wenige (das heißt, acht Menschenleben) durchs Wasser hindurchgerettet wurden.',
        21: 'Dementsprechend rettet jetzt auch euch die Taufe – nicht das Entfernen von körperlichem Schmutz, sondern die an Gott [gerichtete] Bitte eines guten Gewissens – durch die Auferstehung von Jesus Christus,',
        22: 'der zur Rechten Gottes ist, nachdem er in den Himmel gegangen ist, wobei ihm Engel und Mächte und Kräfte untergeben sind.',
    },
    4: {
        1: 'Da also Christus im Fleisch gelitten hat, sollt auch ihr euch mit derselben Gesinnung wappnen; denn wer im Fleisch gelitten hat, hat Schluss gemacht mit Sünde,',
        2: 'um die verbleibende Zeit im Fleisch nicht mehr für die Begierden der Menschen zu leben, sondern für den Willen Gottes.',
        3: 'Denn die vergangene Zeit [war] ausreichend, um den Willen der Heiden vollbracht zu haben, als ihr in Ausschweifungen, Begierden, Trunkenheit, Fress\xadorgien, Saufereien, und verbotenem Götzendienst gelebt habt.',
        4: 'Dadurch sind sie befremdet, da ihr nicht in derselben Welle der Verschwendung mitlauft, sodass sie [über euch] lästern;',
        5: 'sie werden dem Rechenschaft ablegen, der bereit ist, die Lebenden und die Toten zu richten.',
        6: 'Denn dazu ist auch den Toten die gute Nachricht verkündet worden, damit sie zwar gemäß der Menschen im Fleisch gerichtet werden, aber im Geist gemäß Gott leben.',
        7: 'Nun ist das Ende aller [Dinge] nahegekommen. Seid also besonnen und nüchtern zu den Gebeten,',
        8: 'vor allem haltet die Liebe füreinander aufrecht; denn „Liebe bedeckt eine Menge Sünden“.',
        9: '[Seid] gastfreundlich zueinander ohne Murren!',
        10: 'So wie [überhaupt] jeder eine Gnadengabe erhalten hat, um damit einander zu dienen, als gute Haushalter der vielfältigen Gnade Gottes.',
        11: 'Wenn jemand redet, dann wie mit Aussprüchen Gottes; wenn jemand dient, dann wie aus der Kraft, die Gott verschafft, damit in allem Gott verherrlicht wird durch Jesus Christus, dem die Herrlichkeit und die Macht ‹für immer und ewig› gebührt, amen.',
        12: 'Ihr Geliebten, seid nicht befremdet angesichts der Hitze unter euch (wenn sie geschieht, ‹um euch zu testen›), als würde euch etwas Fremdartiges passieren,',
        13: 'sondern freut euch in dem Maß, wie ihr teilhabt an den Leiden des Christus, damit ihr euch auch bei der Offenbarung seiner Herrlichkeit freut und jubelt.',
        14: 'Wenn ihr aufgrund des Namens Christi beschimpft werdet, dann [seid ihr] beglückwünschenswert, denn Gottes Geist der Herrlichkeit ruht auf euch.',
        15: 'Denn niemand von euch soll als Mörder oder Dieb oder Übeltäter oder als Herumschnüffler leiden.',
        16: 'Wenn aber [jemand] als Christ [leidet], dann soll er sich nicht schämen, sondern Gott in dieser Lage verherrlichen.',
        17: 'Denn die Zeit [ist gekommen], dass das Gericht beim Haus Gottes beginnt. Aber wenn [es] zunächst bei uns [beginnt], was [ist] das Ende derer, die der guten Nachricht Gottes ungehorsam sind?',
        18: 'Und wenn der Gerechte knapp gerettet wird, wo wird der Gottlose und Sünder erscheinen!?!',
        19: 'Darum sollen auch diejenigen, die nach Gottes Willen leiden, dem treuen Schöpfer ihre Seelen anvertrauen, während sie Gutes tun.',
    },
    5: {
        1: 'Die Ältesten unter euch ermahne ich als der Mitälteste und Zeuge der Leiden des Christus sowie als Teilhaber an der Herrlichkeit, die offenbart werden soll:',
        2: 'Weidet die Herde Gottes bei euch, beaufsichtigt sie nicht gezwungenermaßen, sondern freiwillig, ‹wie es Gott entspricht›; nicht aus Profitgier, sondern bereitwillig;',
        3: 'auch nicht als [solche], die die Zugeteilten beherrschen, sondern indem ihr Vorbilder für die Herde seid –',
        4: 'wenn dann der Oberhirte erscheint, werdet ihr den unverwelklichen Siegeskranz der Herrlichkeit in Empfang nehmen.',
        5: 'Genauso sollt ihr Jüngeren euch den Ältesten unterordnen! Ihr alle aber sollt euch einander gegenüber mit Demut bekleiden, denn „Gott widersteht den Hochmütigen, den Demütigen aber gibt er Gnade“.',
        6: 'Fügt euch also demütig unter die mächtige Hand Gottes, damit er euch zu [seiner] Zeit erhöht,',
        7: 'indem ihr alle eure Sorge auf ihn werft, weil er für euch sorgt.',
        8: 'Seid nüchtern, seid wachsam! Euer Widersacher, der Teufel, geht umher wie ein brüllender Löwe und sucht, wen er verschlingen kann.',
        9: 'Widersteht ihm, fest im Glauben, und wisst, dass dieselben Arten von Leiden durch eure Glaubensgeschwister in der Welt vollendet werden.',
        10: 'Der Gott aber aller Gnade, der euch berufen hat zu seiner ewigen Herrlichkeit in Christus, der wird euch, nachdem ihr für kurze [Zeit] gelitten habt, wiederherstellen, stärken, kräftigen, gründen.',
        11: 'Ihm [sei] die Macht ‹für immer›, amen.',
        12: 'Durch Silvanus, den treuen Bruder (wie ich meine), habe ich euch mit wenigen [Worten] geschrieben, um euch zu ermutigen und um zu bezeugen, dass dies die wahre Gnade Gottes ist; in der steht fest.',
        13: 'Es grüßen euch die mitauserwählte [Gemeinde] in Babylon und mein Sohn Markus.',
        14: 'Grüßt einander mit dem Kuss der Liebe. Friede [sei] mit euch allen, die [ihr] in Christus [seid]!',
    },
}
